function CodeBlock({ lines }) {
  return (
    <pre className="overflow-hidden rounded-xl border border-edge/70 bg-[#0b0d11] p-4 text-left font-mono text-[12px] leading-[1.6]">
      {lines.map((l, i) => (
        <span key={i} className="block whitespace-pre text-mist transition-colors hover:text-paper">
          <span className="mr-4 inline-block w-5 text-right text-edge select-none">{i + 1}</span>
          {l}
        </span>
      ))}
    </pre>
  )
}

